SELECT array_to_string(array_agg(pod.id), ',') AS id, po.purchase_org_name, pos.supplier_name, pd.images_url, pod.sku_no, pd."name" AS productName, pi.spu_no, avg(pod.tax_price) AS tax_price, round(SUM(pod.purchase_amount) / COUNT(pod.id)::numeric ,4) AS avgPrice, COUNT(po.id) AS orderQty, SUM(pod.purchase_amount) AS orderAmount, max(po.create_time) AS createTime FROM purchase_order_detail pod LEFT JOIN purchase_order po ON pod.purchase_order_id = po.id LEFT JOIN purchase_order_supplier pos ON pos.purchase_order_id = po.id LEFT JOIN product_detail pd ON pod.sku_id = pd.id LEFT JOIN product_info pi ON pi.id = pd.product_id WHERE pod.is_deleted = FALSE AND po.is_deleted = FALSE AND pos.is_deleted = FALSE AND pd.is_deleted = FALSE AND pi.is_deleted = FALSE
AND po.purchase_date >= #{params.billDateList[0]} AND (#{params.billDateList[1]}::TIMESTAMP + INTERVAL '1 DAY' ) >= po.purchase_date
AND pod.sku_no IN
#{item}
AND pod.sku_no IN
#{item}
AND po.delivery_warehouse_id in
#{item}
AND po.purchase_org_id in
#{item}
AND pos.supplier_id in
#{item}
GROUP BY po.purchase_org_name, pos.supplier_name, pd.images_url, pod.sku_no, pd."name", pi.spu_no ORDER BY po.purchase_org_name, pos.supplier_name, max(po.create_time) DESC

